import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { useAuth } from "../../context/AuthContext";
// Navbar is removed to avoid double header
import { FaCloudUploadAlt, FaTimes } from "react-icons/fa";
import "./AddPetPage.css";

const AddPetPage = () => {
    const { user } = useAuth();
    const navigate = useNavigate();

    const [images, setImages] = useState([]);
    const [loading, setLoading] = useState(false);

    const [formData, setFormData] = useState({
        name: "", breed: "", age: "", type: "Dog",
        gender: "Male", color: "", description: "",
        adoptionStatus: "AVAILABLE",
        shelterEmail: user?.email || ""
    });

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleImageChange = (e) => {
        const files = Array.from(e.target.files);
        files.forEach(file => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onloadend = () => {
                setImages((prev) => [...prev, reader.result]);
            };
        });
    };

    const removeImage = (index) => {
        setImages(images.filter((_, i) => i !== index));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            const petData = {
                ...formData,
                age: parseInt(formData.age),
                ownerId: user.uid,
                imageUrl: images[0] || "",
                images: images
            };

            await axios.post("http://localhost:8080/pets", petData);
            alert("Pet added successfully!");
            navigate("/");
        } catch (error) {
            console.error("Error adding pet:", error);
            alert("Failed to add pet.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="add-pet-container">
            <div className="form-wrapper">
                <h2>Add a New Pet 🐾</h2>
                <form onSubmit={handleSubmit}>

                    {/* ROW 1: Name and Breed (2 Columns) */}
                    <div className="form-row">
                        <input
                            name="name"
                            placeholder="Pet Name"
                            onChange={handleChange}
                            required
                        />
                        <input
                            name="breed"
                            placeholder="Breed"
                            onChange={handleChange}
                            required
                        />
                    </div>

                    {/* ROW 2: Age, Type, Gender (3 Columns) */}
                    <div className="form-row three-cols">
                        <input
                            name="age"
                            type="number"
                            placeholder="Age"
                            onChange={handleChange}
                            required
                        />

                        <div className="select-container">
                            <select name="type" onChange={handleChange} value={formData.type}>
                                <option value="Dog">Dog</option>
                                <option value="Cat">Cat</option>
                                <option value="Bird">Bird</option>
                                <option value="Other">Other</option>
                            </select>
                        </div>

                        <div className="select-container">
                            <select name="gender" onChange={handleChange} value={formData.gender}>
                                <option value="Male">Male</option>
                                <option value="Female">Female</option>
                            </select>
                        </div>
                    </div>

                    {/* IMAGE UPLOAD AREA */}
                    <div className="image-upload-section">
                        <label className="upload-btn">
                            <FaCloudUploadAlt size={20} />
                            <span>Upload Photos</span>
                            <input
                                type="file"
                                multiple
                                accept="image/*"
                                onChange={handleImageChange}
                                style={{ display: 'none' }}
                            />
                        </label>

                        {/* Preview Grid */}
                        {images.length > 0 && (
                            <div className="preview-grid">
                                {images.map((img, index) => (
                                    <div key={index} className="preview-card">
                                        <img src={img} alt="preview" />
                                        <button type="button" onClick={() => removeImage(index)}>
                                            <FaTimes />
                                        </button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    <textarea
                        name="description"
                        placeholder="Tell us the story of this pet..."
                        onChange={handleChange}
                        required
                    />

                    <button type="submit" className="submit-btn" disabled={loading}>
                        {loading ? "Saving..." : "List Pet"}
                    </button>
                </form>
            </div>
        </div>
    );
};

export default AddPetPage;
